itTs = getRuntimeContext().getState(\n                    new ValueStateDescriptor<>(\"lastSubmitTs\", Long.class));\n            currentStageCount = getRuntimeContext().getState(\n                    new ValueStateDescriptor<>(\"currentStageCount\", Long.class));\n            bestStageCount = getRuntimeContext().getState(\n                    new ValueStateDescriptor<>(\"bestStageCount\", Long.class));\n            terminalTs = getRuntimeContext().getState(\n                    new ValueStateDescriptor<>(\"terminalTs\", Long.class));\n        }\n\n        @Override\n        public void processElement(\n                org.apache.flink.api.java.tuple.Tuple3<Long, Long, Integer> value,\n                Context ctx,\n                Collector<String> out) throws Exception {\n\n            long ts = value.f1;\n            int kind = value.f2;\n\n            if (kind == 0) {\n                Long last = lastSubmitTs.value();\n                Long curr = currentStageCount.value();\n                Long best = bestStageCount.value();\n                if (best == null) best = 0L;\n\n                if (last == null || ts - last > GAP_MS) {\n                    if (curr != null && curr > best) best = curr;\n                    curr = 1L;\n                } else {\n                    curr = (curr == null ? 1L : curr + 1L);\n                }\n                lastSubmitTs.update(ts);\n                currentStageCount.update(curr);\n                bestStageCount.update(best);\n            } else {\n                // Defer terminal emission until watermark passes terminalTs\n                // so any late SUBMITs with ts <= terminalTs are counted first.\n                Long existing = terminalTs.value();\n                long t = (existing == null) ? ts : Math.min(existing, ts);\n                terminalTs.update(t);\n                ctx.timerService().registerEventTimeTimer(t);\n            }\n        }\n\n        @Override\n        public void onTimer(long timestamp, OnT